///
/// ```
/// use async_trait::async_trait;
/// use futures_core::stream::BoxStream;
/// use paigasus_helikon_core::{
///     CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent,
///     ModelRequest,
/// };
///
/// struct NoopModel;
///
/// #[async_trait]
/// impl Model for NoopModel {
///     async fn invoke(
///         &self,
///         _request: ModelRequest,
///         _cancel: CancellationToken,
///     ) -> Result<
///         BoxStream<'static, Result<ModelEvent, ModelError>>,
///         ModelError,
///     > {
///         Err(ModelError::Unavailable)
///     }
///
///     fn capabilities(&self) -> ModelCapabilities {
///         ModelCapabilities::default()
///     }
/// }
/// ```
#[async_trait]
pub trait Model: Send + Sync {
    /// Invoke the model. Returns a stream of [`ModelEvent`]s on success or a
    /// [`ModelError`] if the request could not be sent. Individual events in
    /// the stream may themselves carry a [`ModelError`].
    ///
    /// **Event-ordering contract:**
    /// - `TokenDelta`, `ReasoningDelta`, and `ToolCallDelta` may interleave
    ///   freely while the model is generating.
    /// - `Usage` MAY appear anywhere; most providers emit one immediately
    ///   before `Finish`, while Anthropic emits cumulative-within-response
    ///   updates. Each `Usage` is a complete snapshot (last-wins): consumers
    ///   retain the last seen and never sum `Usage` events within a turn.
    ///   See [`ModelEvent::Usage`].
    /// - `Finish` is the terminal event; nothing follows it.
    /// - An `Err` item is terminal for every event except `Usage`: implementations MUST NOT yield
    ///   any item after an `Err` other than `Usage` snapshots for the same response.
    /// - Implementations MUST emit `Finish` at end-of-stream when a stop
    ///   reason was observed, and MUST NOT emit it on truncation with no stop
    ///   reason observed, on cancellation, or after a mid-stream error.
    ///
    /// Implementations that cannot honor cancellation MUST still terminate
    /// the stream when the [`CancellationToken`] fires (drop the underlying
    /// connection and end the stream without emitting `Finish`).
    async fn invoke(
        &self,
        request: ModelRequest,
        cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError>;

    /// Provider capabilities. Stable across calls.
    fn capabilities(&self) -> ModelCapabilities;

    /// GenAI `gen_ai.provider.name` — the provider identifier (e.g.
    /// `"openai"`, `"anthropic"`). Providers override this; the `"unknown"`
    /// default is only recorded for a `Model` that does not.
    fn provider(&self) -> &str {
        "unknown"
    }

    /// GenAI `gen_ai.request.model` — the configured model id (e.g.
    /// `"gpt-4o"`). Providers override this; the empty default is only
    /// recorded for a `Model` that does not.
    fn model(&self) -> &str {
        ""
    }
}

/// The request envelope crossing the model boundary.
///
/// Carries the conversation, the tools available for the model to

///     }
/// }
/// ```
#[async_trait]
pub trait Runner<Ctx>: Send + Sync
where
    Ctx: Send + Sync + 'static,
{
    /// Run the agent to completion and return the aggregated result.
    ///
    /// **With a `Session`** (always present on [`RunContext`]): the runner loads
    /// persisted history at start and seeds the conversation as
    /// `history ++ input.messages`, so `input` is the *new turn* — the session
    /// owns history. The run's events are persisted at exit. To continue with no
    /// new turn (or to retry a failed run without re-appending the user message),
    /// use [`Runner::resume`].
    ///
    /// **The returned future must be polled to completion for the run's events to
    /// be persisted.** Finalization happens inside this future, so — as with any
    /// future — dropping it early cancels the work still in flight, including the
    /// session write, and the turn is lost. A caller that cannot guarantee it will
    /// poll to completion (an HTTP handler whose client may disconnect, say) should
    /// drive the run on a detached task and await its result over a channel, rather
    /// than awaiting it inline.
    ///
    /// **Conversely, this future issues the session write before it resolves**, so
    /// callers may treat its resolution as an ordering barrier: the finalize step is
    /// ordered before `run` returns, not left in flight behind it. This is what makes
    /// "detach and await the result over a channel" a sufficient remedy for the hazard
    /// above. Note this is an ordering guarantee, not a durability one: persistence is
    /// best-effort, so an implementation may log rather than propagate an append
    /// failure, and a run that fails before the agent starts never reaches finalize at
    /// all. There are two strict cases. A run that ends with `RunDeferred` and a run
    /// that resumes deferred tool calls must not lose the write. On an append failure
    /// they return [`RunError::SessionWrite`]: the session lost the deferral, or the
    /// results of calls that may have run.
    ///
    /// **Deferred tool calls.** A run whose input has resolutions, or whose session has
    /// open deferrals ([`crate::open_deferrals`]), resumes the deferred calls. The
    /// runner validates the request with [`crate::ResumePlan::from_events`] before the
    /// agent starts. An invalid request returns [`RunError::InvalidResume`], and the
    /// runner records nothing. A runner that does not support resume must reject a run
    /// on a session with open deferrals (use [`crate::open_deferrals`]). Otherwise its
    /// run puts a user message after a `ToolCall` that has no result.
    ///
    /// **One writer per session at a time.** The host must make sure of this (for
    /// example with a lease). Two resumes of one session at the same time can both run
    /// an approved tool.
    ///
    /// **Cancellation/timeout is best-effort and loses to a genuine terminal
    /// event that already occurred.** If the run reaches a terminal
    /// (`RunCompleted`/`RunFailed`/`RunDeferred`/`RunStopped`) before — or in the same poll as — a cancel or
    /// timeout, the runner reports that real outcome (`Ok`, or the structured
    /// `Err(RunError::Agent(..))`), not `Err(RunError::Cancelled)` /
    /// `Err(RunError::Timeout)`. The cancel/timeout wins only when it aborted the
    /// run in-flight, before any terminal event. A caller therefore cannot assume
    /// "I called `cancel()` ⇒ I get `Cancelled`".
    /// Implementors must apply this rule via [`effective_interrupt`] rather
    /// than re-deriving it; [`RunInterrupt`] names the two boundary interrupts.
    async fn run(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        input: AgentInput,
        config: RunConfig,
    ) -> Result<RunResult, RunError>;

    /// Run the agent and return a streaming result handle.
    ///
    /// Session loading/seeding matches [`Runner::run`]. **The returned stream
    /// must be driven to its terminal for the run's events to be persisted:** a
    /// consumer that drops the stream early may skip the finalize step and leave
    /// a partial turn (or nothing) written. In the two strict cases of
    /// [`Runner::run`] (a run that defers or resumes), the `TokioRunner` replaces the
    /// terminal event with `RunFailed` ("session write failed: ...") when an append
    /// fails. It does this also when the run was cancelled or timed out. It records
    /// the error in a [`SessionWriteSlot`], so [`RunResultStreaming::collect`] returns
    /// [`RunError::SessionWrite`], as [`Runner::run`] does. The `TemporalRunner` and
    /// the HTTP runtimes do not support deferred tool calls. They have no strict
    /// case, so they do not make this replacement.
    ///
    /// The same cancellation precedence as [`Runner::run`] applies: once a real
    /// terminal event has been yielded, a late cancel/timeout does not append a
    /// second, synthetic terminal — the stream ends after the real one.
    /// Gate the synthetic terminal on [`effective_interrupt`], and build it with
    /// [`RunInterrupt::terminal_event`] rather than assembling the frame by hand.
    async fn run_streamed(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        input: AgentInput,
        config: RunConfig,
    ) -> Result<RunResultStreaming, RunError>;

    /// Resume a run from the session's persisted history with no new input.
    ///
    /// Equivalent to [`Runner::run`] with an empty [`AgentInput`]: the runner
    /// loads the conversation from `ctx.session()` and continues it. Use this to
    /// continue a multi-turn session, or to retry a failed run without
    /// re-appending the previous turn's user message. (With a `Session` present,
    /// [`Runner::run`]'s `input` is the *new turn*; the session owns history.)
    ///
    /// The empty input has no resolutions. So on a session with open deferred
    /// tool calls, this returns [`RunError::InvalidResume`]. To resume deferred
    /// calls, use [`Runner::run`] with an input that resolves each open call.
    async fn resume(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        config: RunConfig,
    ) -> Result<RunResult, RunError> {
        self.run(agent, ctx, AgentInput::new(), config).await
    }

    /// Streaming counterpart of [`Runner::resume`]: resumes from session
    /// history with no new input and returns a streaming result handle instead
    /// of an aggregated [`RunResult`].
    ///
    /// As with [`Runner::resume`], a session with open deferred tool calls
    /// gives [`RunError::InvalidResume`].
    async fn resume_streamed(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        config: RunConfig,
    ) -> Result<RunResultStreaming, RunError> {
        self.run_streamed(agent, ctx, AgentInput::new(), config)
            .await
    }
}

/// Per-run configuration.
///
/// SMA-314 shipped `max_turns`; SMA-321 added `timeout` and
/// `parallel_tool_call_limit`. Cancellation is intentionally *not* a field
/// here — the canonical token lives on [`crate::RunContext`].
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct RunConfig {
    /// `[driver-scoped]` Maximum number of model turns before the loop fails
    /// with [`crate::AgentError::MaxTurnsExceeded`]. Honored by the core loop
    /// driver, including on a bare `agent.run()` with no runner. Default `16`.
    pub max_turns: u32,
    /// `[runner-scoped]` Wall-clock deadline for the whole run. Honored ONLY by
    /// a runtime backend (e.g. `TokioRunner`); a bare `agent.run()` cannot time
    /// out (core has no timer). `None` = no deadline.
    pub timeout: Option<Duration>,
    /// `[driver-scoped]` Cap on concurrently-executing tool calls. Honored by
    /// the core loop driver. `None` = unbounded (today's behavior).
    pub parallel_tool_call_limit: Option<NonZeroUsize>,
    /// `[driver-scoped]` Maximum agent-nesting depth across **both** handoff
    /// chains and `AgentAsTool` sub-runs. Each nested agent run increments the
    /// depth; exceeding this fails with
    /// [`crate::AgentError::MaxAgentDepthExceeded`]. Default `8`.
    pub max_agent_depth: u32,
}

