24	/// Read handle for the interrupt committed by [`controlled`], if any.
25	struct InterruptHandle(Arc<Mutex<Option<RunInterrupt>>>);
26	
27	impl InterruptHandle {
28	    fn get(&self) -> Option<RunInterrupt> {
29	        *self.0.lock().unwrap()
30	    }
31	}
32	
33	/// Wrap an agent event stream with cancel/deadline control.
34	///
35	/// Passes agent events through. On cancellation or deadline it commits the
36	/// reason into the returned handle and ends the stream (dropping the inner
37	/// stream cancels nested in-flight awaits within one poll). The interrupt, if
38	/// any, is committed *before* the terminating `None`, so a caller reading the
39	/// handle after draining never sees a stale value. A run that ends naturally
40	/// commits nothing and the handle stays `None`. A stream that ends
41	/// after the token fired commits `Cancelled`.
42	fn controlled(
43	    mut stream: BoxStream<'static, AgentEvent>,
44	    cancel: CancellationToken,
45	    timeout: Option<Duration>,
46	) -> (BoxStream<'static, AgentEvent>, InterruptHandle) {
47	    let cell = Arc::new(Mutex::new(None));
48	    let handle = InterruptHandle(Arc::clone(&cell));
49	    let out = async_stream::stream! {
50	        let sleep = async move {
51	            match timeout {
52	                Some(d) => tokio::time::sleep(d).await,
53	                None => std::future::pending::<()>().await,
54	            }
55	        };
56	        tokio::pin!(sleep);
57	        loop {
58	            tokio::select! {
59	                biased;
60	                maybe_ev = stream.next() => {
61	                    match maybe_ev {
62	                        Some(ev) => yield ev,
63	                        None => {
64	                            // The agent stream ended. If the token fired, the
65	                            // agent ended early because of the cancel (a model
66	                            // must not emit `Finish` on cancel), so record it.
67	                            // A real terminal event still wins in `run`.
68	                            if cancel.is_cancelled() {
69	                                *cell.lock().unwrap() = Some(RunInterrupt::Cancelled);
70	                            }
71	                            break;
72	                        }
73	                    }
74	                }
75	                () = cancel.cancelled() => {
76	                    *cell.lock().unwrap() = Some(RunInterrupt::Cancelled);
77	                    break;
78	                }
79	                () = &mut sleep => {
80	                    *cell.lock().unwrap() = Some(RunInterrupt::TimedOut);
81	                    break;
82	                }
83	            }
84	        }
85	    };
86	    (Box::pin(out), handle)
87	}
