89	/// What [`load_and_record`] gives the run.
90	struct Loaded {
91	    /// The input for the agent.
92	    input: AgentInput,
93	    /// The recorder, seeded with the run's new input messages.
94	    recorder: Arc<Mutex<SessionRecorder>>,
95	    /// `true` when the run resumes deferred tool calls.
96	    resuming: bool,
97	}
98	
99	/// Read the session, make the agent input, and seed a recorder with the run's
100	/// new input messages.
101	///
102	/// A read failure is a hard error: the run cannot faithfully resume from an
103	/// unreadable session, so it fails before the agent starts.
104	///
105	/// The run resumes when the input has resolutions or the log has open
106	/// deferrals. A resume gets a validated [`ResumePlan`]: the plan carries the
107	/// history, and the agent input carries only the new messages. An invalid
108	/// resume fails with `RunError::InvalidResume` before the agent starts, and
109	/// nothing is recorded. Other runs get `history ++ input.messages`, as before.
110	///
111	/// The recorder always gets the run's deferral slot, so a stored
112	/// `ToolDeferred` event holds the raw arguments, not the redacted event copy.
113	async fn load_and_record(
114	    session: &Arc<dyn Session>,
115	    agent_name: &str,
116	    input: AgentInput,
117	    deferrals: DeferralSlot,
118	    max_agent_depth: u32,
119	) -> Result<Loaded, RunError> {
120	    let snapshot = session
121	        .snapshot()
122	        .await
123	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
124	    let events = session
125	        .events(None)
126	        .await
127	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
128	    let resuming = !input.resolutions().is_empty() || !open_deferrals(&events).is_empty();
129	
130	    let mut recorder = SessionRecorder::new(agent_name).with_deferral_slot(deferrals);
131	    let mut agent_input = AgentInput::new();
132	    if resuming {
133	        let plan =
134	            ResumePlan::from_events(&events, &snapshot, agent_name, &input, max_agent_depth)?;
135	        recorder = recorder.with_resume_plan(&plan);
136	        recorder.record_input(&input.messages);
137	        agent_input.messages = input.messages;
138	        agent_input = agent_input.with_resume_plan(plan);
139	    } else {
140	        recorder.record_input(&input.messages);
141	        agent_input.messages = snapshot.messages;
142	        agent_input.messages.extend(input.messages);
143	    }
144	    Ok(Loaded {
145	        input: agent_input,
146	        recorder: Arc::new(Mutex::new(recorder)),
147	        resuming,
148	    })
149	}
