151	/// Post-run finalization: drain the recorder and append the run's events.
152	///
153	/// An append error is logged and returned. The caller decides what it means:
154	/// a run that defers or resumes fails with it (the session lost the deferral
155	/// or the resumed results), and other runs ignore it (best-effort).
156	async fn finalize(
157	    session: &Arc<dyn Session>,
158	    recorder: &Arc<Mutex<SessionRecorder>>,
159	) -> Result<(), SessionError> {
160	    let events = recorder
161	        .lock()
162	        .expect("session recorder mutex poisoned")
163	        .drain();
164	    let result = session.append(&events).await;
165	    if let Err(e) = &result {
166	        tracing::warn!(
167	            target: "paigasus::runtime_tokio::runner",
168	            error = %e,
169	            "session persistence failed during finalize"
170	        );
171	    }
172	    result
173	}
