175	/// Record a lost strict session write and make the `RunFailed` event that
176	/// replaces the run's terminal event.
177	fn lost_write(slot: &SessionWriteSlot, e: SessionError) -> AgentEvent {
178	    let error = format!("session write failed: {e}");
179	    slot.set(e);
180	    AgentEvent::RunFailed { error }
181	}
