206	        // Load persisted history (or the resume plan) and seed the recorder
207	        // with the new turn.
208	        let Loaded {
209	            input,
210	            recorder,
211	            resuming,
212	        } = load_and_record(
213	            &session,
214	            agent.name(),
215	            input,
216	            ctx.deferral_handle(),
