236	            .await;
237	        let written = finalize(&session, &recorder).await;
238	
239	        // A run that defers or resumes must not lose its write: the session
240	        // would lose the deferral, or the results of calls that may have run.
241	        // This error wins over the agent result and the interrupt.
242	        let deferred = matches!(
243	            &collected,
244	            Ok(r) if matches!(r.stop_reason, StopReason::Deferred { .. })
