755	/// Accumulates one run's semantic items as [`SessionEvent`]s for the runner to
756	/// persist at run exit.
757	///
758	/// The runner pre-seeds the recorder with the run's `AgentInput` messages (the
759	/// new turn — which the agent does not re-emit on its event stream), then feeds
760	/// it every [`crate::AgentEvent`] as the stream flows. [`SessionRecorder::drain`]
761	/// returns the accumulated log, synthesizing a [`SessionEvent::ToolReturned`]
762	/// for any tool call left without a result (a run interrupted mid-tool) so the
763	/// log always [`project`]s to a provider-valid conversation. A deferred call
764	/// gets no synthetic result: it waits for a host decision.
765	///
766	/// On a resume ([`SessionRecorder::with_resume_plan`]), the results of the
767	/// resumed calls go before the recorded input. If the agent rejects the resume
768	/// before it gives a result for a resumed call, the recorder records nothing,
769	/// and the deferrals stay open.
770	#[derive(Debug)]
771	pub struct SessionRecorder {
772	    events: Vec<SessionEvent>,
773	    current_agent: String,
774	    deferral_slot: Option<crate::DeferralSlot>,
775	    /// The call ids of the resumed calls (empty when the run is no resume).
776	    resume_call_ids: Vec<String>,
777	    /// The tool results that the agent emits before its first turn.
778	    resume_block: Vec<SessionEvent>,
779	    /// `true` until the first `TurnStarted` of a resumed run.
780	    in_resume_window: bool,
781	    /// `true` when the agent rejected the resume: a `RunFailed` came in the
782	    /// resume window before a result for a resumed call.
783	    resume_rejected: bool,
784	}
785	
786	impl SessionRecorder {
787	    /// Create a recorder seeded with the root agent's name. Used to attribute
788	    /// assistant messages whose [`Item::AssistantMessage`] `agent` is `None`,
789	    /// before any `RunStarted`/`AgentUpdated` updates the tracked agent.
790	    pub fn new(root_agent: impl Into<String>) -> Self {
791	        Self {
792	            events: Vec::new(),
793	            current_agent: root_agent.into(),
794	            deferral_slot: None,
795	            resume_call_ids: Vec::new(),
796	            resume_block: Vec::new(),
797	            in_resume_window: false,
798	            resume_rejected: false,
799	        }
800	    }
801	
802	    /// Wire the resume plan of a resumed run.
803	    ///
804	    /// The runner records the new input before the stream starts, but the
805	    /// results of the resumed calls must come before that input in the log.
806	    /// So the recorder keeps every tool result that the agent emits before its
807	    /// first `TurnStarted` apart, and [`SessionRecorder::drain`] puts these
808	    /// results first. A resumed call with no result gets the synthetic
809	    /// cancel result in the same place, so the deferral is closed.
810	    ///
811	    /// The one exception is a rejected resume. An agent that cannot resume
812	    /// (for example a workflow agent) emits `RunFailed` before it gives a
813	    /// result for a resumed call. No resumed call started, so
814	    /// [`SessionRecorder::drain`] then returns no events: the session keeps
815	    /// its open deferrals, and a later resume can still resolve them. An
816	    /// `LlmAgent` that ends before it runs the calls gives a "did not run"
817	    /// result for each call before its `RunFailed`, so this exception does
818	    /// not apply to it. A cancel or a timeout emits no `RunFailed`, so a
819	    /// resumed call that started still gets the synthetic cancel result.
820	    #[must_use]
821	    pub fn with_resume_plan(mut self, plan: &crate::ResumePlan) -> Self {
822	        self.resume_call_ids = plan.call_ids();
823	        self.in_resume_window = true;
824	        self
825	    }
826	
827	    /// Wire the run's deferral slot. The slot holds the raw arguments of the
828	    /// deferred calls. The recorder persists these raw arguments in
829	    /// [`SessionEvent::ToolDeferred`], because the resume runs the tool with
830	    /// exactly these arguments. The arguments in [`AgentEvent::RunDeferred`]
831	    /// can be redacted.
832	    #[must_use]
833	    pub fn with_deferral_slot(mut self, slot: crate::DeferralSlot) -> Self {
834	        self.deferral_slot = Some(slot);
835	        self
836	    }
837	
838	    /// Record the run's input messages (the new turn). The agent never re-emits
839	    /// these on its event stream, so the runner records them directly.
840	    /// [`Item::System`] has no [`SessionEvent`] equivalent and is skipped.
841	    pub fn record_input(&mut self, messages: &[Item]) {
842	        for item in messages {
843	            match item {
