854	                    call_id,
855	                    name,
856	                    args,
857	                } => {
858	                    self.events.push(SessionEvent::tool_called(
859	                        call_id.clone(),
860	                        name.clone(),
861	                        args.clone(),
862	                    ));
863	                }
864	                Item::ToolResult { call_id, content } => {
865	                    self.events.push(SessionEvent::tool_returned(
866	                        call_id.clone(),
867	                        content.clone(),
868	                    ));
869	                }
