917	            } => {
918	                let event = SessionEvent::tool_returned(call_id.clone(), content.clone());
919	                if self.in_resume_window {
920	                    self.resume_block.push(event);
921	                } else {
922	                    self.events.push(event);
923	                }
924	            }
925	            AgentEvent::HandoffItem { from, to } => {
926	                self.events
