485	    /// Drain the stream and deserialize the terminal assistant text into `T`.
486	    ///
487	    /// The terminal output is the concatenated text of the last
488	    /// [`AgentEvent::MessageOutput`]. On a correctly configured structured run
489	    /// the agent loop has already validated that text against `T`, so the parse
490	    /// here is expected to succeed; if it fails (e.g. `collect_typed` is called
491	    /// on a plain-text run), the parse error surfaces as [`AgentError::Other`].
492	    /// A failed run surfaces the underlying [`AgentError`]:
493	    /// structured-validation failures (carried by
494	    /// [`AgentEvent::StructuredOutputFailed`]) become
495	    /// [`AgentError::InvalidStructuredOutput`]; any other terminal
496	    /// [`AgentEvent::RunFailed`] becomes [`AgentError::Other`].
497	    ///
498	    /// A run that did not complete (a terminal [`AgentEvent::RunDeferred`] or
499	    /// [`AgentEvent::RunStopped`]) returns [`AgentError::Incomplete`] with its
500	    /// stop reason.
501	    pub async fn collect_typed<T>(mut self) -> Result<RunResult<T>, AgentError>
502	    where
503	        T: serde::de::DeserializeOwned,
504	    {
505	        use futures_util::stream::StreamExt;
506	        let mut events = Vec::new();
507	        let mut final_text = String::new();
508	        let mut usage = crate::TokenUsage::default();
509	        let mut stop_reason = crate::StopReason::Completed;
510	        let mut structured_err: Option<(Vec<String>, String)> = None;
511	        let mut failed: Option<String> = None;
512	
513	        while let Some(ev) = self.events.next().await {
514	            match &ev {
515	                // See `collect`: a provider-data-only message has no text.
516	                AgentEvent::MessageOutput {
517	                    item: item @ Item::AssistantMessage { content, .. },
518	                } if !item.is_provider_data_only() => {
519	                    final_text.clear();
520	                    for part in content {
521	                        if let ContentPart::Text { text } = part {
522	                            final_text.push_str(text);
523	                        }
524	                    }
525	                }
526	                AgentEvent::RunCompleted { usage: u } => usage = *u,
527	                AgentEvent::RunDeferred { calls, usage: u } => {
528	                    usage = *u;
529	                    stop_reason = crate::StopReason::Deferred {
530	                        calls: calls.clone(),
531	                    };
532	                }
533	                AgentEvent::RunStopped { reason, usage: u } => {
534	                    usage = *u;
535	                    stop_reason = crate::StopReason::Stopped {
536	                        reason: reason.clone(),
537	                    };
538	                }
539	                AgentEvent::StructuredOutputFailed {
540	                    schema_errors,
541	                    final_text: ft,
542	                } => {
543	                    structured_err = Some((schema_errors.clone(), ft.clone()));
544	                }
545	                AgentEvent::RunFailed { error } => {
546	                    failed = Some(error.clone());
547	                }
548	                _ => {}
549	            }
550	            events.push(ev);
551	        }
552	
553	        if let Some(e) = self.take_session_write() {
554	            return Err(AgentError::Session(e));
555	        }
556	        if let Some(err_msg) = failed {
557	            // Primary: the structured side-channel (populated post-drain).
558	            if let Some(err) = self.failure.as_ref().and_then(FailureSlot::take) {
559	                return Err(err);
560	            }
561	            // Fallback 1: reconstruct InvalidStructuredOutput from its event.
562	            if let Some((schema_errors, final_text)) = structured_err {
563	                return Err(AgentError::InvalidStructuredOutput {
564	                    schema_errors,
565	                    final_text,
566	                });
567	            }
568	            // Fallback 2: the opaque string.
569	            return Err(AgentError::Other(anyhow::anyhow!(err_msg)));
570	        }
571	
572	        if stop_reason != crate::StopReason::Completed {
573	            return Err(AgentError::Incomplete { stop_reason });
574	        }
575	
576	        let final_output = serde_json::from_str::<T>(final_text.trim()).map_err(|e| {
577	            AgentError::Other(anyhow::anyhow!(
578	                "collect_typed: failed to deserialize final output: {e}"
579	            ))
580	        })?;
581	        Ok(RunResult {
582	            final_output,
583	            events,
584	            usage,
585	            stop_reason,
586	        })
587	    }
