        .into_iter()
        .map(|o| AgentEvent::ToolOutputItem {
            item: Item::ToolResult {
                call_id: o.call_id,
                content: o
                    .result
                    .unwrap_or_else(|e| vec![ContentPart::Text { text: e }]),
