async fn backoff(cancel: &CancellationToken, d: Duration) -> bool {
    tokio::select! {
        biased;
        () = cancel.cancelled() => false,
        () = tokio::time::sleep(d) => true,
    }
}

#[async_trait]
impl<M: Model + 'static> Model for RetryingModel<M> {
    async fn invoke(
        &self,
        request: ModelRequest,
        cancel: CancellationToken,
